export class PlaceHierarchy { #nodes=new Map(); add(node){if(!node?.id||!node?.type)throw new TypeError('id/type required');this.#nodes.set(node.id,structuredClone(node));return this;} ancestors(id){const out=[];let n=this.#nodes.get(id);const seen=new Set();while(n?.parentId&&!seen.has(n.parentId)){seen.add(n.parentId);n=this.#nodes.get(n.parentId);if(n)out.push(structuredClone(n));}return out;} resolve(id){const n=this.#nodes.get(id);return n?{...structuredClone(n),ancestors:this.ancestors(id)}:null;} }
